mapper.select:
SELECT GROUP_ID, OWNER_ID, MAX_MEMBERS, STATUS, ORDER_CONFIRMED_YN
FROM GYE_GROUP
WHERE GROUP_ID = #{groupId}

SELECT PAYOUT_REQUEST_ID, GROUP_ID, MEMBER_ID, ROUND_NO, STATUS
FROM PAYOUT_REQUEST
WHERE GROUP_ID = #{groupId}
  AND MEMBER_ID = #{memberId}
  AND STATUS IN ('REQUESTED', 'CONSENT_PENDING')
  AND ROWNUM = 1

SELECT PAYOUT_REQUEST_ID, GROUP_ID, MEMBER_ID, ROUND_NO, REASON, STATUS
FROM PAYOUT_REQUEST
WHERE PAYOUT_REQUEST_ID = #{payoutRequestId}

mapper.insert:
INSERT INTO PAYOUT_REQUEST (
    PAYOUT_REQUEST_ID, GROUP_ID, MEMBER_ID, ROUND_NO, REASON, AI_SUGGESTED_ROUND, STATUS, CREATED_AT
) VALUES (
             SEQ_PAYOUT_REQUEST.NEXTVAL, #{groupId}, #{memberId}, #{roundNo}, #{reason}, #{aiSuggestedRound}, 'REQUESTED', SYSDATE
         )

mapper.delete:
DELETE FROM CONSENT
WHERE CONSENT_TYPE = 'ORDER'
  AND TARGET_ID = #{payoutRequestId}

mapper.select:
SELECT MEMBER_ID
FROM GYE_MEMBER
WHERE GROUP_ID = #{groupId}
  AND STATUS = 'ACTIVE'
  AND MEMBER_ID != #{excludeMemberId}

mapper.insert:
INSERT INTO CONSENT (
    CONSENT_ID, CONSENT_TYPE, TARGET_ID, GROUP_ID, MEMBER_ID, AGREED_YN, AGREED_AT
) VALUES (
             SEQ_CONSENT.NEXTVAL, 'ORDER', #{targetId}, #{groupId}, #{memberId}, 'N', SYSDATE
         )

mapper.update:
UPDATE CONSENT
SET AGREED_YN = #{agreedYn},
    AGREED_AT = SYSDATE
WHERE CONSENT_TYPE = 'ORDER'
  AND TARGET_ID = #{targetId}
  AND MEMBER_ID = #{memberId}

mapper.select:
SELECT COUNT(*)
FROM GYE_MEMBER
WHERE GROUP_ID = #{groupId}
  AND STATUS = 'ACTIVE'
  AND MEMBER_ID != #{applicantId}

SELECT COUNT(*)
FROM PAYOUT_REQUEST
WHERE GROUP_ID = #{groupId}
  AND ROUND_NO = #{roundNo}
  AND STATUS = 'CONFIRMED'
  AND PAYOUT_REQUEST_ID != #{excludeRequestId}

mapper.update:
UPDATE GYE_GROUP
SET ORDER_CONFIRMED_YN = #{yn}
WHERE GROUP_ID = #{groupId}

mapper.insert:
INSERT INTO NOTIFICATION (
    NOTIFICATION_ID, MEMBER_ID, NOTIF_TYPE, TITLE, BODY, READ_YN, DELETED_YN, SMS_SENT_YN, CREATED_AT
) VALUES (
             SEQ_NOTIFICATION.NEXTVAL, #{memberId}, #{notifType}, #{title}, #{body}, 'N', 'N', 'N', SYSDATE
         )

INSERT INTO AUDIT_LOG (
    AUDIT_LOG_ID, GROUP_ID, ACTOR_MEMBER_ID, EVENT_TYPE, DESCRIPTION, CREATED_AT
) VALUES (
             SEQ_AUDIT_LOG.NEXTVAL, #{groupId}, #{actorId}, #{eventType}, #{description}, SYSDATE
         )
